#!/usr/bin/env python3
import os, subprocess, stat, pathlib

def write(path, content, mode=0o644):
    p = pathlib.Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(content)
    p.chmod(mode)
    print("wrote", path)

# --- sshd ---
write("/etc/ssh/sshd_config.d/99-git.conf", """PasswordAuthentication yes
PubkeyAuthentication yes
PermitRootLogin yes
UsePAM yes
KbdInteractiveAuthentication yes
PermitTTY yes
""")

# relax host key checking for local clones
write("/etc/ssh/ssh_config.d/99-local.conf", """Host localhost 127.0.0.1 ::1
    StrictHostKeyChecking no
    UserKnownHostsFile /dev/null
    LogLevel ERROR
""")

# --- deploy targets ---
for d in ("/var/www/main", "/var/www/dev"):
    os.makedirs(d, exist_ok=True)
    subprocess.run(["chown", "-R", "git:git", d], check=True)
    os.chmod(d, 0o755)

# --- post-receive hook ---
write("/git/project/hooks/post-receive", """#!/bin/bash
set -e
GIT_DIR=/git/project
unset GIT_QUARANTINE_PATH
while read -r oldrev newrev ref; do
    branch="${ref#refs/heads/}"
    case "$branch" in
        main) target=/var/www/main ;;
        dev)  target=/var/www/dev ;;
        *) continue ;;
    esac
    mkdir -p "$target"
    git --git-dir=/git/project --work-tree="$target" checkout -f "$branch" >/dev/null 2>&1
    git --git-dir=/git/project --work-tree="$target" clean -fd >/dev/null 2>&1 || true
    chmod -R a+rX "$target" || true
    echo "deployed $branch -> $target"
done
""", 0o755)
subprocess.run(["chown", "-R", "git:git", "/git"], check=True)

# --- self-signed cert ---
os.makedirs("/etc/nginx/certs", exist_ok=True)
subprocess.run(["openssl", "req", "-x509", "-nodes", "-newkey", "rsa:2048",
                "-days", "3650", "-subj", "/CN=localhost",
                "-addext", "subjectAltName=DNS:localhost,IP:127.0.0.1",
                "-keyout", "/etc/nginx/certs/server.key",
                "-out", "/etc/nginx/certs/server.crt"], check=True)
os.chmod("/etc/nginx/certs/server.key", 0o600)

# --- nginx site ---
write("/etc/nginx/conf.d/deploy.conf", """server {
    listen 8443 ssl;
    listen [::]:8443 ssl;
    server_name localhost;

    ssl_certificate     /etc/nginx/certs/server.crt;
    ssl_certificate_key /etc/nginx/certs/server.key;

    root /var/www/main;
    index index.html;
    autoindex off;

    location /dev/ {
        alias /var/www/dev/;
        index index.html;
        try_files $uri $uri/index.html =404;
    }

    location / {
        try_files $uri $uri/ =404;
    }
}
""")
print("done")

